head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.noti_seq = '';
scwin.isur_cd = '';
scwin.dep_cd = '';
scwin.gLastJob = '';
scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        scwin.initPage();
        $c.cm.PanelToGroupBox(panel_1);
        await scwin.read();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10803.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Transmit_onclick
 * @description 「접수」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Transmit_onclick = async function() {
    try {
        await scwin.transmit('T');
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10803.btn_Transmit_onclick" });
    }
};

/**
 * @method
 * @name btn_Return_onclick
 * @description 「반송」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Return_onclick = async function() {
    try {
        await scwin.transmit('R');
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10803.btn_Return_onclick" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnFail = async function() {
    try {
        await scwin.alert_error2(trs_Save);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10803.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        const msg = $c.stf.getMessageParam("MSG-A001", scwin.gLastJob);
        await $c.win.alert(msg);
        /*
        var fr_fn_read = frame.Provider("../").fn_read;
        frame.CloseFrame();
        fr_fn_read();
         */
        const fr_fn_search = $c.frame.path("../").fn_Search;
        await $c.win.closePopup();
        fr_fn_search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10803.trs_Save_OnSuccess" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name read
 * @description read 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.read = async function() {
    url += "&NOTI_SEQ=" + txb_NOTI_SEQ.getValue();
    url += "&ISUR_CD=" + txb_ISUR_CD.getValue();
    url += "&SCREN_ID=" + 'ULDSTF10803.xml';
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions = {
        id : "sbm_dts_MASTER",
        action : "/OnlineNotice.do",
        ref : "",
        target : "dts_MASTER=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name initPage
 * @description init Page 처리
 * @returns {void}
 * @hidden N
 */
scwin.initPage = function() {
    scwin.noti_seq = frame.opener.dts_Grid.getCellData(frame.opener.key_row, 'NOTI_SEQ');
    scwin.isur_cd = frame.opener.dts_Grid.getCellData(frame.opener.key_row, 'ISUR_CD');
    scwin.dep_cd = scwin.gDepCd;
    txb_NOTI_SEQ.setValue(scwin.noti_seq);
    txb_ISUR_CD.setValue(scwin.isur_cd);
    txb_NOTI_SEQ.hide();
    txb_ISUR_CD.hide();
    txb_DEP_CD.hide();
    txb_MODE.hide();
    txb_EMP_NO.hide();
    // showObj(txb_DUTY_YN, false);

    // 반송은 공시팀만 가능하다. 다른팀은 반송사유,반송버튼은 보이지 않게 한다.
    // 상품관리팀 20130415 상품 관리팀 제외.
    // if(gDepCd == '2220' || gDepCd == '2430' || gDepCd == '2B20') {
    if (scwin.gDepCd === '2220' || scwin.gDepCd === '2430') {
        label_6.hide();
        txb_RET_RSN.hide();
        btn_Return.hide();
        panel_1.style.height = 190;
        btn_Transmit.style.top = 157;
    }
};

/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {void}
 * @hidden N
 */
scwin.setCode = function() {
    // dts_MASTER.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=KIFRS_LIST";

};

/**
 * @method
 * @name transmit
 * @description T : 전송, R 반송
 * @param {*} mode mode
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.transmit = async function(mode) {
    // T : 전송, R 반송

    if (mode === 'T') {
        scwin.gLastJob = "접수";
        txb_MODE.setValue("T");
        txb_RET_RSN.setValue("");
    } else {
        scwin.gLastJob = "반송";
        txb_MODE.setValue("R");
        if (txb_RET_RSN.getValue() === '') {
            await $c.win.alert("반송시 반송사유를 입력하셔야 합니다.");
            txb_RET_RSN.focus();
            return;
        }
    }
    // 당번여부 셋팅
    let duty_yn = "N";
    if (js_duty === "Y" || js_duty_chrg === "Y") {
        duty_yn = "Y";
    }
    txb_DUTY_YN.setValue(duty_yn);
    txb_NOTI_SEQ.setValue(scwin.noti_seq);
    txb_ISUR_CD.setValue(scwin.isur_cd);
    txb_DEP_CD.setValue(scwin.dep_cd);
    txb_EMP_NO.setValue(scwin.gEmpNo);
    const res = window.confirm("[" + scwin.gLastJob + "]하시겠습니까?");
    if (res) {
        let url = "/OnlineNotice.do?method=notiTeamAcpt" + "&SCREN_ID=" + 'ULDSTF10803.xml' + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        // alert(dts_MASTER.Text);
        trs_Save.Action = url;
        trs_Save.KeyName = "toinb_dataid4";
        trs_Save.KeyValue = "JSP(I:pInputMaster=dts_MASTER)";
        trs_Save.post();
    }
};

/**
 * @method
 * @name alert_error2
 * @description alert error2 처리
 * @param {*} dtsObj dtsObj
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.alert_error2 = async function(dtsObj) {
    const USER_DEFINE = new Array("INTERNAL", "UNDEFINED", "APP_COMPONENT", "BIZ_COMPONENT", "ACTION", "CORE_FRAMEWORK", "WEB_FRAMEWORK", "INFO");
    for (let i = 0; i < USER_DEFINE.length; i++) {
        const errorCount = dtsObj.SrvErrCount(USER_DEFINE[i]);
        let j;
        for (j = 0; j < errorCount; j++) {
            if (dtsObj.SrvErrCode(USER_DEFINE[i], j) === '0') {
                // '0' 임의로 떨군 INFO 메시지
                await $c.win.alert(dtsObj.SrvErrMsg(USER_DEFINE[i], j));
            } else {
                // 기존 에러 메시지
                await $c.win.alert("[CODE: " + dtsObj.SrvErrCode(USER_DEFINE[i], j) + "] " + dtsObj.SrvErrMsg(USER_DEFINE[i], j));
            }
        }
    }
};
